\begin{theorem}\label{night:P2.2}\label{stmt:P2.2}


On $q=Q^{12}$, actual extending origins have lifts
\begin{align*}
 o&=\binom{-b\mu s/2}{bs^2/24-bCs/12+l_0s/2+v(bs+U)},\\
 \sigma&=-l_0z_\gamma+\binom{6a\mu v}{vU+aCv-6av^2+6av}.
\end{align*}
The section $\sigma$ extends across the cusp for $r\ne0$, and $o$ extends across the parameter central fibre of the partial filling. Their difference is
\begin{equation}\label{eq:P2F}
 F=\sigma-o=a\binom{\mu(s+12v)/2}{C(s+12v)/12-(s+12v)^2/24+6v}.
\end{equation}
On $q=Q^{12m}$, $r=R^n$, with $m,n$ positive integers,
\begin{align}
 \Delta_QF&=am\gamma-6am^2\delta,\label{eq:P2FQ}\\
 \Delta_RF&=an\gamma-6an(n-1)\delta.\label{eq:P2FR}
\end{align}
The radial class modulo $\Z\widehat\delta$ is $-pn\widehat\gamma$. The proposed $+pn\widehat\gamma$ has the opposite sign in the fixed conventions.
\end{theorem}

\begin{proposition}[Counterexample: the proposed normalization]\label{maps:src:E.1.1}



The local space $(F\times_{\widetilde\Delta}E)/\mu_m$ in Lead 6 is not
the normalization of the literal fibre product $X\times_B S$ at an
additive fibre.  It is a different proper model of its punctured family.

\end{proposition}

\begin{theorem}[the integral cusp calculation]\label{maps:src:E.1.3}



For the central fibre $W_3$ of \eqref{maps:eq:E.5},
\[
 H_q(W_3;\mathbb Z)=\mathbb Z^{b_q},\qquad
 (b_0,\ldots,b_6)=(1,3,9,9,10,3,1).
 \tag{E.6}\label{maps:eq:E.6}
